import{_ as l,a0 as o,w as d,s as r,I as t,x as e,a1 as i,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"學習如何高效地使用 man 頁 | LCTT x X-CMD","titleTemplate":false,"description":"學習如何高效地使用 man 頁 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"學習如何高效地使用 man 頁 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"學習如何高效地使用 man 頁 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171215 Learn To Use Man Pages Efficiently","title":"學習如何高效地使用 man 頁","tag":"201712","desc":""},"relativePath":"201712/20171215 Learn To Use Man Pages Efficiently.md","filePath":"[post].md"}'),c={name:"201712/20171215 Learn To Use Man Pages Efficiently.md"};function h(g,a,m,k,u,b){const s=o("Link");return d(),r("div",null,[a[19]||(a[19]=t("h1",{id:"學習如何高效地使用-man-頁",tabindex:"-1"},[e("學習如何高效地使用 man 頁 "),t("a",{class:"header-anchor",href:"#學習如何高效地使用-man-頁","aria-label":"Permalink to “學習如何高效地使用 man 頁”"},"​")],-1)),t("p",null,[a[1]||(a[1]=e("不久前，我們發佈了一篇簡短的指引描述瞭如何輕易地",-1)),i(s,{href:"https://www.ostechnix.com/easily-recall-forgotten-linux-commands/"},{default:n(()=>[...a[0]||(a[0]=[e("回憶起忘記的 Linux 命令 ",-1)])]),_:1}),a[2]||(a[2]=e("。那篇指引對於無法記住命令的人來説真的非常有用。今天，我們就來學習一下如何高效而又迅速地從 man 頁中獲取你所需要的信息。如你所知，一個標準的 man 頁分成很多個部分，每部分都有一個獨立的標題。當你想查看特定的標誌/選項時，可能需要向下滾動很長時間才能找到。這是個效率底下而且很耗時間的過程。這也是為什麼學會高效使用 man 頁來精確定位你想要的內容。",-1))]),a[20]||(a[20]=p(`<p>在本文中，我會分享一些常用的跟 man 頁相關的重要技巧。</p><h3 id="學習高效地使用-man-頁" tabindex="-1">學習高效地使用 Man 頁 <a class="header-anchor" href="#學習高效地使用-man-頁" aria-label="Permalink to “學習高效地使用 Man 頁”">​</a></h3><h4 id="基礎用法" tabindex="-1">基礎用法 <a class="header-anchor" href="#基礎用法" aria-label="Permalink to “基礎用法”">​</a></h4><p>我們都知道，我們可以使用類似下面的命令來打開關於某個命令（比如 <code>mkdir</code>）的 man 頁：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir</span></span></code></pre></div><p>可以使用 <code>空格</code>，<code>d</code>，<code>b</code> 以及上下箭頭等來瀏覽 man 頁。要跳轉道 man 頁的末尾，可以按 <code>End</code> 鍵而想跳轉到 man 頁的頭部則可以按 <code>Home</code> 鍵。在當前打開的 man 頁中按下 <code>h</code> 鍵會顯示所有有用的鍵盤快捷鍵和一般用法。（LCTT 譯註：這些快捷鍵其實是 man 所使用的 less 分頁器的快捷鍵）</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-4.png" alt=""></p><p>按 <code>q</code> 可以退出 man 頁。</p><h4 id="回憶起忘記的命令" tabindex="-1">回憶起忘記的命令 <a class="header-anchor" href="#回憶起忘記的命令" aria-label="Permalink to “回憶起忘記的命令”">​</a></h4><p>對於那些不知道想要哪個命令的傢伙，可以去查看一下我第一段中提到的那個鏈接。使用 man 頁我們也能做到這一點。假設説，你想要創建一個目錄，而你忘記了使用哪個命令來創建目錄。</p><p>為了回憶起那個忘記的命令，可以將 man 和 <code>grep</code> 命令聯用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man -k directory | grep create</span></span></code></pre></div><p>輸出結果為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CURLOPT_NEW_DIRECTORY_PERMS (3) - permissions for remotely created directories</span></span>
<span class="line"><span>libssh2_sftp_mkdir_ex (3) - create a directory on the remote file system</span></span>
<span class="line"><span>mkdir (2) - create a directory</span></span>
<span class="line"><span>mkdirat (2) - create a directory</span></span>
<span class="line"><span>mkdtemp (3) - create a unique temporary directory</span></span>
<span class="line"><span>mkdtemp (3p) - create a unique directory or file</span></span>
<span class="line"><span>mkfontdir (1) - create an index of X font files in a directory</span></span>
<span class="line"><span>mklost+found (8) - create a lost+found directory on a mounted Linux second extended file。。。</span></span>
<span class="line"><span>mkstemp (3p) - create a unique directory</span></span>
<span class="line"><span>mktemp (1) - create a temporary file or directory</span></span>
<span class="line"><span>pam_mkhomedir (8) - PAM module to create users home directory</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-3.png" alt=""></p><p>你只需要閲讀一下每個命令的描述然後挑選出合適的命令就行了。啊，現在你記起來了。<code>mkdir</code> 正式你想要的，對吧？就是那麼簡單。</p><h4 id="在-man-頁中搜索" tabindex="-1">在 man 頁中搜索 <a class="header-anchor" href="#在-man-頁中搜索" aria-label="Permalink to “在 man 頁中搜索”">​</a></h4><p>若你在 man 頁中想要查找特定字符串。只需要輸入 <code>/</code> （前斜線）再加上你想要搜索的字符串，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/&lt;search_string&gt; 或 &lt;pattern&gt;</span></span></code></pre></div><p>假設你正在查看 <code>mount</code> 命令的 man 頁，想要尋找關於 <code>-bind</code> 選項的相關信息。可以輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/bind</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-5.png" alt=""></p><p>當前 man 頁中任何匹配搜索字符串的內容都會被高亮顯示。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-6.png" alt=""></p><p>按下 <code>n</code> 和 <code>SHIFT+n</code> 來查看下一個/上一個匹配的地方。</p><p><code>/</code> 模式（或者説字符串）會向前搜索匹配行。你也可以使用 <code>?</code> 模式進行向後搜索。這當你在 man 頁的末尾或中間位置時非常有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?bind</span></span></code></pre></div><p>若想只顯示匹配行，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&amp;bind</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-8.png" alt=""></p><p>使用這種方法，你無需使用 <code>n</code> 和 <code>SHIFT+n</code> 來滾動到下一個/上一個匹配的位置。<code>&amp;</code> 模式只會顯示那些包含搜索內容的行，其他的內容全都被省略掉。</p><h4 id="不打開-man-頁而進行搜索" tabindex="-1">不打開 man 頁而進行搜索 <a class="header-anchor" href="#不打開-man-頁而進行搜索" aria-label="Permalink to “不打開 man 頁而進行搜索”">​</a></h4><p>也可以在不打開 man 頁的前提下搜索指定選項的信息。</p><p>比如，你想了解 <code>mkdir</code> 命令中的 <code>-m</code> 選項的相關信息。可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir | grep -e &#39;-m&#39;</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir | grep -- &#39;-m&#39;</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-1.png" alt=""></p><p>這個命令會顯示出 <code>mkdir</code> 命令 man 頁中第一次出現 <code>-m</code> 時的內容。從上面命令中我們可以看到 <code>-m</code> 表示的是 “MODE”（<code>chmod</code>）。</p><p>如果你想閲讀 <code>mkdir</code> 命令的完整 man 頁，但是要跳過第一次出現 <code>-m</code> 之前的內容，可以使用下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir | less +/-m</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-2-1.png" alt=""></p><p>這是另一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mount | less +/--bind</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/12/man-pages-7.png" alt=""></p><p>按下 <code>n</code> 或 <code>SHIFT+n</code> 可以瀏覽下一個/上一個匹配的位置。</p>`,46)),t("p",null,[a[4]||(a[4]=e("參考閲讀：",-1)),i(s,{href:"https://www.ostechnix.com/3-good-alternatives-man-pages-every-linux-user-know/"},{default:n(()=>[...a[3]||(a[3]=[e("每個 Linux 用户都應該知道的 3 個 man 頁替代品",-1)])]),_:1}),a[5]||(a[5]=e("。",-1))]),a[21]||(a[21]=p('<h4 id="將完整的-man-頁導出到文本文件中" tabindex="-1">將完整的 man 頁導出到文本文件中 <a class="header-anchor" href="#將完整的-man-頁導出到文本文件中" aria-label="Permalink to “將完整的 man 頁導出到文本文件中”">​</a></h4><p>我們可以將指定命令的完整 man 頁導出成文本文件。方法是運行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mount &gt; mount.txt</span></span></code></pre></div><p>該命令會將 <code>mount</code> 命令的 man 頁導出到當前目錄的 <code>mount.txt</code> 文件中。</p><p>也可以獲取一個簡化版的 man 頁，沒有退格和下劃線，方法是使用下面命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mount | col -b &gt; mount.txt</span></span></code></pre></div><p>要了解更多關於 man 頁的詳細信息，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man man</span></span></code></pre></div><p>該命令會顯示出關於 man 的 man 頁。這些技巧都很基礎但很實用。它們會節省你很多的時間而且能免去很多的滾動操作。</p><p>今天的內容就到這了。希望對你有幫助。更多好文即將到來。準備好哦！</p><p>Cheers！</p><hr>',12)),t("p",null,[a[7]||(a[7]=e("via: ",-1)),i(s,{href:"https://www.ostechnix.com/learn-use-man-pages-efficiently/"},{default:n(()=>[...a[6]||(a[6]=[e("https://www.ostechnix.com/learn-use-man-pages-efficiently/",-1)])]),_:1})]),t("p",null,[a[11]||(a[11]=e("作者：",-1)),i(s,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...a[8]||(a[8]=[e("SK",-1)])]),_:1}),a[12]||(a[12]=e(" 譯者：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[9]||(a[9]=[e("lujun9972",-1)])]),_:1}),a[13]||(a[13]=e(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...a[10]||(a[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[16]||(a[16]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[14]||(a[14]=[e("LCTT",-1)])]),_:1}),a[17]||(a[17]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...a[15]||(a[15]=[e("Linux中國",-1)])]),_:1}),a[18]||(a[18]=e(" 榮譽推出",-1))])])}const w=l(c,[["render",h]]);export{x as __pageData,w as default};
